package br.com.tapeteskalke.repository; import br.com.tapeteskalke.entity.OrdemProducao; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface OrdemProducaoRepository extends JpaRepository<OrdemProducao,String> { @EntityGraph(attributePaths={"produtoAcabado","cliente","materiasPrimas","materiasPrimas.produtoMateriaPrima"}) @Query("select o from OrdemProducao o where o.id=:id") Optional<OrdemProducao> detail(@Param("id")String id); @Query("select o from OrdemProducao o join fetch o.produtoAcabado order by o.numeroOrdem desc") List<OrdemProducao> listWithProduct(); }
